function obtenerColorDominante(u){return new Promise(d=>{try{const h=document.createElement("canvas"),m=h.getContext("2d"),a=20;h.width=a,h.height=a;const r=new Image;r.crossOrigin="Anonymous",r.src=u.src,r.onload=()=>{m.drawImage(r,0,0,a,a);let t=0,n=0,o=0,s=0;try{const e=m.getImageData(0,0,a,a).data;for(let c=0;c<e.length;c+=4)t+=e[c],n+=e[c+1],o+=e[c+2],s++;t=Math.round(t/s),n=Math.round(n/s),o=Math.round(o/s);const g=.75;t=Math.round(t+(255-t)*g),n=Math.round(n+(255-n)*g),o=Math.round(o+(255-o)*g),d(`rgb(${t}, ${n}, ${o})`)}catch{d("#f0e4d3")}},r.onerror=()=>d("#f0e4d3")}catch{d("#f0e4d3")}})}
